CREATE TABLE eip_payment_transactions (
 id uuid PRIMARY KEY, tenant_id uuid NOT NULL, merchant_reference varchar(120) NOT NULL, payer_reference varchar(160), amount numeric(19,4) NOT NULL, currency varchar(3) NOT NULL, payment_channel varchar(30) NOT NULL, connector_code varchar(100) NOT NULL, idempotency_key varchar(180) NOT NULL, payment_status varchar(30) NOT NULL, provider_reference varchar(180), authorized_at timestamptz, completed_at timestamptz, failure_code varchar(100), failure_message text, created_at timestamptz NOT NULL, created_by varchar(255), updated_at timestamptz NOT NULL, updated_by varchar(255), version bigint NOT NULL, status varchar(30) NOT NULL, CONSTRAINT ux_eip_payment_idempotency UNIQUE(tenant_id,idempotency_key));
CREATE INDEX ix_eip_payment_reference ON eip_payment_transactions(tenant_id,merchant_reference); CREATE INDEX ix_eip_payment_status ON eip_payment_transactions(tenant_id,payment_status,created_at);
CREATE TABLE eip_payment_provider_attempts (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,payment_transaction_id uuid NOT NULL REFERENCES eip_payment_transactions(id),attempt_number int NOT NULL,connector_code varchar(100) NOT NULL,attempt_status varchar(30) NOT NULL,provider_request_id varchar(180),provider_response_code varchar(100),provider_response_message text,submitted_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL,created_by varchar(255),updated_at timestamptz NOT NULL,updated_by varchar(255),version bigint NOT NULL,status varchar(30) NOT NULL); CREATE INDEX ix_eip_payment_attempt_tx ON eip_payment_provider_attempts(tenant_id,payment_transaction_id,attempt_number);
CREATE TABLE eip_payment_settlements (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,connector_code varchar(100) NOT NULL,provider_settlement_reference varchar(180) NOT NULL,settlement_date date NOT NULL,gross_amount numeric(19,4) NOT NULL,fee_amount numeric(19,4) NOT NULL,net_amount numeric(19,4) NOT NULL,currency varchar(3) NOT NULL,settlement_status varchar(30) NOT NULL,created_at timestamptz NOT NULL,created_by varchar(255),updated_at timestamptz NOT NULL,updated_by varchar(255),version bigint NOT NULL,status varchar(30) NOT NULL,CONSTRAINT ux_eip_settlement_provider_ref UNIQUE(tenant_id,connector_code,provider_settlement_reference));
CREATE TABLE eip_payment_reconciliations (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,payment_transaction_id uuid,settlement_id uuid,provider_reference varchar(180),internal_amount numeric(19,4),provider_amount numeric(19,4),reconciliation_status varchar(30) NOT NULL,reconciled_at timestamptz,notes text,created_at timestamptz NOT NULL,created_by varchar(255),updated_at timestamptz NOT NULL,updated_by varchar(255),version bigint NOT NULL,status varchar(30) NOT NULL); CREATE INDEX ix_eip_recon_status ON eip_payment_reconciliations(tenant_id,reconciliation_status,created_at);
CREATE TABLE eip_payment_disputes (id uuid PRIMARY KEY,tenant_id uuid NOT NULL,payment_transaction_id uuid NOT NULL REFERENCES eip_payment_transactions(id),reason_code varchar(100) NOT NULL,description text NOT NULL,dispute_status varchar(30) NOT NULL,resolved_at timestamptz,resolution_notes text,created_at timestamptz NOT NULL,created_by varchar(255),updated_at timestamptz NOT NULL,updated_by varchar(255),version bigint NOT NULL,status varchar(30) NOT NULL);
